"""Exact original break records for the private nominal-ray corner branch.

Ordinary side layouts read only owner/t/break from the former dense clearance
table. They evaluate their own full boundary and profile charts at every mesh
station. Keep every original curve/contact break but do not build unused
clearance samples, positions, normals or curvature caps. Legacy diagnostics and
the allocated-depth fallback keep their original dense table.

Compound/chain tables are deliberately unchanged: their initial-placement
heuristic may consume the full table's positions. This is an ordinary-boundary
optimization, not a new limitation on the supported network configurations.
"""
import hashlib

from . import curved_clearance_nodes as clearance
from .curved_quad_fair_nodes import assign_group

c=clearance.c
boundary=clearance.boundary


def prove_parameter_range_only(tree):
    """Fail closed if chart Valid depends on interior t beyond its range.

    All omitted samples are convex combinations of consecutive retained knots.
    Their t is in [0,1]. Any future non-range t dependency requires review;
    evaluating it only at knots would not be an equivalent validity check.
    Conservatively traverse every input of any encountered node/group call.
    """
    output,=[n for n in tree.nodes if n.type=='GROUP_OUTPUT' and n.is_active_output]
    visited=set()
    def visit(socket):
        if socket in visited:return
        visited.add(socket);node=socket.node
        if node.type=='GROUP_INPUT':
            if socket.name=='t':raise ValueError('Unproved interior-parameter validity dependency: '+tree.name)
            return
        if node.bl_idname=='ShaderNodeMath' and node.operation in ('GREATER_THAN','LESS_THAN'):
            links=node.inputs[0].links
            if len(links)==1 and links[0].from_node.type=='GROUP_INPUT' and links[0].from_socket.name=='t':
                bound=node.inputs[1]
                enclosed=(node.operation=='GREATER_THAN' and bound.default_value<0.) or (
                    node.operation=='LESS_THAN' and bound.default_value>1.)
                if not bound.is_linked and enclosed:return
        for inp in node.inputs:
            for link in inp.links:visit(link.from_socket)
    for link in output.inputs['Valid'].links:visit(link.from_socket)


def build(original):
    name=original.name
    if (not name.startswith('Prochitecture Streets / Original curved boundary samples with knots')
            or ' / Original Section ports' not in name
            or any(part in name for part in (' / Compound arcs',' / Original span sides',' / Original chain sides'))):
        raise ValueError('Station-only records require the ordinary original-port contract: '+name)
    chart,=[n for n in original.nodes if n.type=='GROUP' and n.label=='Sample unchanged original curved boundary']
    prove_parameter_range_only(chart.node_tree)
    # Use the saved chart, not a separately rebuilt interpretation of its math.
    for key,value in (('v',0.),('Guide Narrowing',0.)):
        socket=chart.inputs[key]
        if socket.is_linked or socket.default_value!=value:
            raise ValueError('Unsupported original chart setting: '+key)
    result=original.copy();result.nodes.clear()
    result.name='Prochitecture Streets / Original boundary break records / '+hashlib.sha256(name.encode()).hexdigest()[:16]
    g=c.Graph.__new__(c.Graph);g.g=result;g.count=0;g.frame=None
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    count=c._count(g,inp.outputs['Mouths']);size=c.V(g,inp.outputs['Samples Per Side'])
    valid=c.V(g,inp.outputs['Boundary Valid'])*g.math('GREATER_THAN',size,2.5)
    valid*=g.math('LESS_THAN',count*size,clearance.MAX_SAMPLES+.5)
    ri=g.node('GeometryNodeRepeatInput','Retain exact original boundary breaks only')
    ro=g.node('GeometryNodeRepeatOutput');ri.pair_with_output(ro)
    g.bind(c.choose(g,valid,count,0,'INT'),ri.inputs['Iterations']);side=c.V(g,ri.outputs['Iteration'])
    parameters,parameters_valid,dense_count=clearance._parameters(g,inp,side,size,
        continuations=' / Curb continuations' in name,port_paths=True,
        interpolation=' / Exact entrance rays' in name,
        resolvable_contact_samples=' / Resolvable contact splits' in name,knots_only=True)
    parameters=c._store(g,parameters,'st_cg_t',g.separate(g.position())[0])
    call=g.node('GeometryNodeGroup','Unchanged chart validity; no unused clearance geometry')
    call.node_tree=chart.node_tree
    for key in ('Sources','Mapping','Approaches','Corners','Mouths','Boundary Valid'):
        g.bind(inp.outputs[key],call.inputs[key])
    g.bind(side,call.inputs['Index']);g.bind(c.named(g,'st_cg_t'),call.inputs['t'])
    g.bind(0.,call.inputs['v']);g.bind(0.,call.inputs['Guide Narrowing'])
    for key,value,kind in (('st_cg_owner',side,'INT'),
        ('st_cg_valid',c.V(g,call.outputs['Valid'])*parameters_valid,'BOOLEAN'),
        ('st_direct_station_only',True,'BOOLEAN')):
        parameters=c._store(g,parameters,key,value,kind)
    index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
    parameters=c._store(g,parameters,'_st_dense_sample_budget',
        c.choose(g,g.math('LESS_THAN',index,.5),dense_count,0.),'INT')
    g.bind(boundary._join(g,ri.outputs['Geometry'],parameters),ro.inputs['Geometry'])
    geo=ro.outputs['Geometry']
    valid*=c._stat(g,geo,c.named(g,'st_cg_valid','BOOLEAN'))
    valid*=g.math('LESS_THAN',c._stat(g,geo,c.named(g,'_st_dense_sample_budget','INT'),'Sum'),clearance.MAX_SAMPLES+.5)
    g.bind(geo,out.inputs['Geometry']);g.bind(valid,out.inputs['Valid'])
    result['st_boundary_station_only']=1
    return result


def replace_saved(roots):
    """Replace only the station-table input of proven direct ordinary branches."""
    memo={};changes=[];skipped=[];tables={}
    def visit(tree):
        if tree in memo:return memo[tree]
